import{_ as i,o as s,c as e,a2 as t}from"./chunks/framework.KobcctIO.js";const u=JSON.parse('{"title":"Multi-Platform Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/players/installation.md","filePath":"guide/players/installation.md"}'),n={name:"guide/players/installation.md"};function l(o,a,r,p,d,h){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="multi-platform-installation" tabindex="-1">Multi-Platform Installation <a class="header-anchor" href="#multi-platform-installation" aria-label="Permalink to &quot;Multi-Platform Installation&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Windows-10%20%2F%2011-blue.svg" alt="Windows"><img src="https://img.shields.io/badge/macOS-Intel%20%26%20Apple%20Silicon-lightgrey.svg" alt="macOS"><img src="https://img.shields.io/badge/Linux-AppImage%20%26%20APT-red.svg" alt="Linux"></div><p>Gens Launcher is natively available on <strong>Windows</strong>, <strong>macOS</strong>, and <strong>Linux</strong>. Follow the instructions below to set up the software on your operating system.</p><hr><h2 id="windows-10-and-11" tabindex="-1">Windows (10 and 11) <a class="header-anchor" href="#windows-10-and-11" aria-label="Permalink to &quot;Windows (10 and 11)&quot;">​</a></h2><h3 id="download-and-setup" tabindex="-1">Download and Setup <a class="header-anchor" href="#download-and-setup" aria-label="Permalink to &quot;Download and Setup&quot;">​</a></h3><ol><li>Navigate to the <a href="https://github.com/WilliamBossard/Gens-Launcher/releases/latest" target="_blank" rel="noreferrer">Latest GitHub Releases</a>.</li><li>Download the installer file: <strong><code>GensLauncher-Setup-X.X.X.exe</code></strong>.</li><li>Double-click the downloaded executable to begin the NSIS setup wizard.</li></ol><div class="warning custom-block"><p class="custom-block-title">Windows Defender SmartScreen Alert</p><p>Gens Launcher is an independent open-source project. Because the project does not have an expensive commercial corporate certificate (EV Code Signing, costing hundreds of dollars per year), Windows SmartScreen may display a blue warning:<br><em>&quot;Windows protected your PC&quot;</em>.</p><p><strong>To continue installation:</strong></p><ol><li>Click the text link <strong>&quot;More info&quot;</strong>.</li><li>Click the <strong>&quot;Run anyway&quot;</strong> button.</li><li>All source code is completely public and auditable on GitHub; the software is safe.</li></ol></div><hr><h2 id="macos-intel-and-apple-silicon" tabindex="-1">macOS (Intel and Apple Silicon) <a class="header-anchor" href="#macos-intel-and-apple-silicon" aria-label="Permalink to &quot;macOS (Intel and Apple Silicon)&quot;">​</a></h2><ol><li>Download the disk image <strong><code>GensLauncher-X.X.X-mac.dmg</code></strong> from the <a href="https://github.com/WilliamBossard/Gens-Launcher/releases/latest" target="_blank" rel="noreferrer">GitHub Releases</a>.</li><li>Double-click the <code>.dmg</code> file to mount the installation volume.</li><li>Drag and drop the <strong>Gens Launcher</strong> icon into your <strong>Applications</strong> folder shortcut.</li></ol><div class="danger custom-block"><p class="custom-block-title">Mandatory Applications Folder</p><p>You must copy the app into <code>/Applications</code>. If you launch the app directly from the virtual mounted DMG image, the auto-updater will fail to install background updates.</p></div><hr><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><p>We offer two packaging formats for Linux distributions:</p><h3 id="option-1-official-signed-apt-repository-recommended-for-debian-and-ubuntu" tabindex="-1">Option 1: Official Signed APT Repository (Recommended for Debian and Ubuntu) <a class="header-anchor" href="#option-1-official-signed-apt-repository-recommended-for-debian-and-ubuntu" aria-label="Permalink to &quot;Option 1: Official Signed APT Repository (Recommended for Debian and Ubuntu)&quot;">​</a></h3><p>This is the recommended route: it hooks Gens Launcher into your OS package manager for background updates via <code>apt upgrade</code>.</p><p>Open your terminal and run these 3 commands:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Download and import the official GPG signing key</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://williambossard.github.io/Gens-Launcher/public.key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dearmor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/share/keyrings/gens-launcher-keyring.gpg</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Add the Gens Launcher repository to your apt sources</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;deb [signed-by=/usr/share/keyrings/gens-launcher-keyring.gpg] https://williambossard.github.io/Gens-Launcher/ ./&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/apt/sources.list.d/gens-launcher.list</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Update repositories and install Gens Launcher</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gens-launcher</span></span></code></pre></div><p>To update in the future:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --only-upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gens-launcher</span></span></code></pre></div><h3 id="option-2-universal-appimage-package" tabindex="-1">Option 2: Universal AppImage Package <a class="header-anchor" href="#option-2-universal-appimage-package" aria-label="Permalink to &quot;Option 2: Universal AppImage Package&quot;">​</a></h3><p>AppImage runs on any modern Linux distribution (Fedora, Arch Linux, Manjaro, Debian, Ubuntu) without installation:</p><ol><li>Download the <strong><code>GensLauncher-X.X.X.AppImage</code></strong> file.</li><li>Grant execution rights: <ul><li><strong>Terminal:</strong><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GensLauncher-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.AppImage</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./GensLauncher-*.AppImage</span></span></code></pre></div></li><li><strong>File Manager:</strong> Right-click file -&gt; <em>Properties</em> -&gt; <em>Permissions</em> tab -&gt; check <em>&quot;Allow executing file as program&quot;</em>.</li></ul></li><li>Double-click the AppImage to launch the game.</li></ol><hr><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Minimum Specification</th><th>Recommended Specification</th></tr></thead><tbody><tr><td><strong>Operating System</strong></td><td>Windows 10 (64-bit), macOS 11+, Linux 64-bit</td><td>Windows 11, macOS 14+, Ubuntu 24.04 LTS</td></tr><tr><td><strong>System RAM</strong></td><td>4 GB</td><td>8 to 16 GB</td></tr><tr><td><strong>Free Disk Space</strong></td><td>2 GB for launcher and vanilla Minecraft</td><td>10+ GB (for larger modpacks and shader caches)</td></tr><tr><td><strong>Java Runtime</strong></td><td>Java 8, 17, or 21 (depending on Minecraft version)</td><td><strong>Managed automatically by Gens Launcher</strong></td></tr></tbody></table>`,27)])])}const g=i(n,[["render",l]]);export{u as __pageData,g as default};
